using UnityEngine;using UnityEditor;using System;using System.IO;using System.Linq;using System.Text;
namespace Skywright.Editor {public static class MeadowAssetInspection {
 public static void Import(){AssetDatabase.ImportPackage("Evidence/FinishedMeadow/SelectedForest.unitypackage",false);AssetDatabase.Refresh();Inspect();}
 public static void Inspect(){var b=new StringBuilder();foreach(var guid in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/ALP_Assets"})){var path=AssetDatabase.GUIDToAssetPath(guid);var p=AssetDatabase.LoadAssetAtPath<GameObject>(path);var g=UnityEngine.Object.Instantiate(p);g.transform.position=Vector3.zero;var rs=g.GetComponentsInChildren<Renderer>();var bounds=new Bounds();bool first=true;foreach(var r in rs){if(first){bounds=r.bounds;first=false;}else bounds.Encapsulate(r.bounds);}b.AppendLine(path+" bounds="+bounds+" colliders="+g.GetComponentsInChildren<Collider>().Length);foreach(var l in g.GetComponentsInChildren<LODGroup>()){foreach(var lod in l.GetLODs())b.AppendLine(" LOD "+lod.screenRelativeTransitionHeight+" tris="+lod.renderers.Sum(r=>r.GetComponent<MeshFilter>()?.sharedMesh?.triangles.Length/3??0));}foreach(var m in rs.SelectMany(r=>r.sharedMaterials).Distinct())b.AppendLine(" material "+(m?m.name+" shader="+m.shader.name+" supported="+m.shader.isSupported:"MISSING"));UnityEngine.Object.DestroyImmediate(g);}File.WriteAllText("Evidence/FinishedMeadow/asset-inspection.txt",b.ToString());Debug.Log("MEADOW_IMPORT_INSPECTED");}
}}
